import {makeBackup,readBackup} from './data.mjs';
let account=null;
async function request(path,method='GET',body){const response=await fetch('/api/'+path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok)throw new Error(data.error||'Request failed.');return data;}
export function mountTransfers(state,{replace,toast}){
 const storageLabel=document.querySelector('#storage-label');if(storageLabel)storageLabel.textContent=window.MANTA_BACKEND?(account?'Workshop draft':'Local server'):'Browser storage';
 const name=document.querySelector('.workspace strong');if(name)name.textContent=account?account.workshop:'Northstar Refurbishing';
 const panel=document.createElement('section');panel.className='panel transfer-panel';panel.setAttribute('aria-label','Workspace storage');
 const title=document.createElement('h2');title.textContent=window.MANTA_BACKEND?'Workshop storage':'Keep your workspace safe';panel.append(title);
 const status=document.createElement('p');status.textContent=account?`${account.workshop} · ${account.email} · revision ${account.revision}. Changes stay in your draft until you save to the workshop.`:window.MANTA_BACKEND?'Sign in or create a workshop. Local server mode keeps unsigned drafts in memory; back up before leaving.':'Download a complete backup to restore your devices, evidence, and planning limits later.';panel.append(status);
 const actions=document.createElement('div');actions.className='transfer-actions';panel.append(actions);
 const button=(label,handler)=>{const b=document.createElement('button');b.type='button';b.className='button';b.textContent=label;b.onclick=async()=>{b.disabled=true;try{await handler();}catch(e){toast(e.message);}finally{b.disabled=false;}};actions.append(b);return b;};
 button('Download backup',()=>{const url=URL.createObjectURL(new Blob([makeBackup(state)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='manta-workspace-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
 function confirmDialog(title,description,commit){const d=document.createElement('dialog');d.setAttribute('aria-labelledby','transfer-title');d.innerHTML='<form><h2 id="transfer-title"></h2><p></p><label class="inline-check"><input type="checkbox" required> Replace my current draft. I have backed up anything I need.</label><div class="dialog-actions"><button type="button" class="button">Cancel</button><button class="button primary">Continue</button></div></form>';d.querySelector('h2').textContent=title;d.querySelector('p').textContent=description;d.querySelector('button').onclick=()=>d.close();d.querySelector('form').onsubmit=async e=>{e.preventDefault();const submit=d.querySelector('[type=submit]')||d.querySelector('.primary');submit.disabled=true;try{await commit();d.close();}catch(err){toast(err.message);submit.disabled=false;}};d.onclose=()=>d.remove();document.body.append(d);d.showModal();}
 button('Restore backup',()=>{const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>2000000)throw new Error('Backup exceeds the 2 MB limit.');const next=readBackup(await file.text());confirmDialog('Restore workspace backup?',`${next.devices.length} devices and ${next.evidence.length} evidence records. This replaces your draft; it does not save to the shared workshop.`,()=>{next.approved=null;replace(next);toast('Backup restored. Review the plan before approval.');});}catch(e){toast(e.message);}};input.click();});
 if(window.MANTA_BACKEND){
  if(!account){
   const auth=register=>{const d=document.createElement('dialog');d.setAttribute('aria-labelledby','account-title');d.innerHTML=`<form><h2 id="account-title">${register?'Create or join a workshop':'Sign in to workshop'}</h2><p>Signing in loads the shared workspace and replaces this draft. Download a backup first if needed.</p><label>Email<input name="email" type="email" maxlength="254" autocomplete="username" required></label><label>Password<input name="password" type="password" minlength="12" maxlength="128" autocomplete="${register?'new-password':'current-password'}" required></label>${register?'<label>New workshop name<input name="workshop" maxlength="100"></label><label>Or invitation code<input name="invite" maxlength="64" autocomplete="off"></label><p>Use a unique password of at least 12 characters. Email verification and password recovery are not available in this local prototype.</p>':''}<p role="alert" class="danger"></p><div class="dialog-actions"><button type="button" class="button">Cancel</button><button class="button primary">${register?'Create account':'Sign in'}</button></div></form>`;d.querySelector('button').onclick=()=>d.close();d.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=d.querySelector('.primary');b.disabled=true;try{account=await request(register?'register':'login','POST',Object.fromEntries(new FormData(e.target)));replace(account.workspace);d.close();toast('Workshop loaded.');}catch(err){d.querySelector('[role=alert]').textContent=err.message;b.disabled=false;}};d.onclose=()=>d.remove();document.body.append(d);d.showModal();};
   button('Sign in',()=>auth(false));button('Create / join workshop',()=>auth(true));
   button('Resume session',()=>confirmDialog('Load your signed-in workshop?','This replaces your current draft with the latest saved workshop.',async()=>{account=await request('session');replace(account.workspace);}));
  }else{
   button('Save to workshop',async()=>{account=await request('workspace','PUT',{workshopId:account.workshopId,revision:account.revision,workspace:state});replace(account.workspace);toast('Saved to shared workshop.');});
   button('Load latest',()=>confirmDialog('Load latest workshop?','Unsaved draft changes will be replaced.',async()=>{account=await request('session');replace(account.workspace);}));
   if(account.role==='owner')button('Invite teammate',async()=>{const result=await request('invites','POST');const d=document.createElement('dialog');d.innerHTML='<h2>Invite a teammate</h2><p>Share this single-use code privately. It grants access to this workshop and expires in 24 hours.</p><label>Invitation code<input readonly></label><div class="dialog-actions"><button class="button">Close</button></div>';d.setAttribute('aria-label','Invite a teammate');d.querySelector('input').value=result.invite;d.querySelector('button').onclick=()=>d.close();d.onclose=()=>d.remove();document.body.append(d);d.showModal();});
   button('Sign out',()=>confirmDialog('Sign out?','Unsaved draft changes will be discarded.',async()=>{await request('logout','POST');account=null;replace(null);toast('Signed out.');}));
  }
 }
 document.querySelector('#app').append(panel);
}
